-- The two checklists published on 2026-10-03: a frightening medical
-- appointment (Health) and a first therapy session (Therapy).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-03`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('before-a-medical-appointment-that-frightens-you', 'Before a Medical Appointment That Frightens You', 'For the days before a scan, a test result or a visit you have been putting off. It helps you get your questions down, bring someone with you, and sit in the waiting room without the fear filling every hour until then.', 'Health', '["Write your three biggest questions on your phone — having them in front of you means the ones that matter get asked.", "Note when your symptoms started and what changes them — that answer is hard to assemble on the spot.", "Ask one person to come with you or be on call — a second set of ears catches what you will not hear.", "Pack water, a snack and something to read — waiting is easier when your body is not also hungry.", "Say out loud what frightens you most about today — naming it leaves you with one worry instead of all of them.", "Put both feet flat on the floor in the waiting room — a steady base gives your body something solid to hold.", "Ask the doctor to write down what you must remember — notes carry better than a memory that is already busy.", "Decide what you will do straight after the visit — a plan for the next hour keeps the day from stopping there."]'::jsonb, 'as needed', array['Anxiety', 'Body']::text[], 1, '2026-10-03T16:00:00+00:00'::timestamptz),
  ('your-first-therapy-session', 'Your First Therapy Session', 'For the week before you first sit down with a therapist. It helps you work out what you want to say, what you want to ask them, and how to get through the first hour without feeling you have to perform.', 'Therapy', '["Write the one thing you most want to change — a single starting point is easier than a whole history.", "Jot down when it started and what you have already tried — it saves you telling the story twice.", "Check how you get there and leave ten minutes spare — arriving rushed costs you the start of the hour.", "Ask what their approach is and how long it usually takes — you are allowed to understand the plan you are in.", "Say at the start if you find it hard to talk — a therapist can work with that once they know.", "Decide what you would rather not cover yet — you set the pace, and saying so is part of the work.", "Keep the hour after it free — what comes up often lands once you are back outside.", "Note one thing afterward that felt useful or off — it tells you whether this is the right fit."]'::jsonb, 'as needed', array['Life Transitions', 'Anxiety']::text[], 1, '2026-10-03T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
